contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address spender, uint256 amount) public {
        require(amount > 0);

        c.approve(spender, amount);

        bool reverted;
        try c.transfer(spender, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(c.allowance(address(this), spender) == amount && reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 shareAmount, uint256 baseMinAmount, uint256 quoteMinAmount, address to, bytes calldata data) public {
        uint256 tsBefore = c.totalSupply();
        uint256 balBefore = c.balanceOf(address(this));

        bool reverted;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, data, 0) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 tsAfter = c.totalSupply();
        uint256 balAfter = c.balanceOf(address(this));

        assert(reverted && tsAfter == tsBefore && balAfter == balBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address owner, address spender, uint256 deadline, uint8 v, bytes32 r, bytes32 s) public {
        require(deadline < block.timestamp);
        uint256 beforeAllowance = c.allowance(owner, spender);

        bool reverted;
        try c.permit(owner, spender, 1, deadline, v, r, s) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(reverted && c.allowance(owner, spender) == beforeAllowance);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 skipAmount) public payable {
        require(skipAmount >= 0);
        (uint256 baseBefore, uint256 quoteBefore) = c.getVaultReserve();
        bool reverted;
        c.sync();
        reverted = false;
        (uint256 baseAfter, uint256 quoteAfter) = c.getVaultReserve();
        assert(!reverted && baseAfter == baseBefore && quoteAfter == quoteBefore);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount) public {
        require(amount > 0);

        // The test contract holds no shares, so grant ourselves an ample
        // allowance first; the transferFrom must still fail on balance.
        c.approve(address(this), type(uint256).max);

        bool reverted;
        try c.transferFrom(address(this), to, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            reverted &&
            c.balanceOf(address(this)) == 0 &&
            c.balanceOf(to) == 0
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 shareAmount, address to, uint256 baseMinAmount, uint256 quoteMinAmount, uint256 deadline) public payable {
        require(deadline < block.timestamp);
        uint256 totalBefore = c.totalSupply();
        uint256 callerBefore = c.balanceOf(address(this));
        uint256 recipientBefore = c.balanceOf(to);
        bool reverted;
        try c.sellShares(shareAmount, to, baseMinAmount, quoteMinAmount, "", deadline) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && c.totalSupply() == totalBefore && c.balanceOf(address(this)) == callerBefore && c.balanceOf(to) == recipientBefore);
    }
    receive() external payable {}
}

